// Código para nó "Code" do n8n
// Converte o cURL PHP original em JavaScript com tratamento de erros

const options = {
  method: 'POST',
  url: 'https://www.autoshoppingformula.com.br/apis/get-token-import',
  headers: {
    'Content-Type': 'application/json',
  },
  body: {
    login: 'agentesdr',
    password: 'nPrYqH7rCsUH328',
    client_id: 'trinix_veiculo',
    token_opc: 1,
  },
  json: true, // garante que o corpo seja enviado e recebido como JSON
};

async function run() {
  try {
    const response = await this.helpers.request(options);

    // Retorna o resultado como um objeto n8n
    return [
      {
        success: true,
        data: response,
      },
    ];
  } catch (error) {
    // Captura e retorna o erro detalhado
    return [
      {
        success: false,
        error: error.message || 'Erro desconhecido',
        stack: error.stack || null,
      },
    ];
  }
}

return run();
